#!/bin/bash
# Print the three most frequent IPs in access.log, one per line,
# most frequent first, ties broken by first appearance in the log.
awk '
{
    ip = $1
    if (!(ip in count)) first[ip] = ++n   # remember first-appearance order
    count[ip]++
}
END {
    # Selection sort: pick the IP with the highest count,
    # breaking ties by earliest first appearance.
    for (i = 1; i <= 3; i++) {
        best = ""
        for (ip in count) {
            if (!(ip in picked)) {
                if (best == "" ||
                    count[ip] > count[best] ||
                    (count[ip] == count[best] && first[ip] < first[best]))
                    best = ip
            }
        }
        if (best == "") break
        picked[best] = 1
        print best
    }
}
' access.log
